package pipeline

import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs. It currently deadlocks on any non-empty input.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	// Start a goroutine to close the jobs channel once all inputs are sent.
	// This prevents the main goroutine from blocking on wg.Wait() while
	// the workers are waiting for more jobs or for the channel to close.
	go func() {
		for i := range inputs {
			jobs <- i
		}
		close(jobs)
	}()

	wg.Wait()
	return out
}
